async function makeThumbnail(file){if(!(file instanceof File)||!file.size)throw new Error("사진을 촬영하거나 선택해 주세요.");const bitmap=await createImageBitmap(file),scale=Math.min(1,960/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext("2d").drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("사진 크기 조정에 실패했습니다.")),"image/webp",.78));return new File([blob],"thumbnail.webp",{type:"image/webp"})}
