function bindPhotoInputs(form){let selectedPhoto=null,objectUrl=null;const preview=document.querySelector("#preview"),name=document.querySelector("#photo-name");for(const input of form.querySelectorAll(".photo-input"))input.onchange=()=>{const file=input.files?.[0];if(!file)return;selectedPhoto=file;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);preview.src=objectUrl;preview.hidden=false;name.textContent=file.name||"촬영한 사진"};return ()=>selectedPhoto}
