function imageViewer(){
 let dialog=document.querySelector("#issue-image-viewer");
 if(!dialog){dialog=document.createElement("dialog");dialog.id="issue-image-viewer";dialog.className="issue-image-viewer";dialog.innerHTML='<div class="viewer-controls"><button type="button" class="viewer-original" aria-label="원본 사진 불러오기">원본 보기</button><button type="button" class="viewer-close" aria-label="확대 사진 닫기">닫기</button></div><div class="viewer-stage"><img alt="확대 사진" tabindex="0" aria-label="확대 사진. 두 번 눌러 확대 또는 축소"></div>';document.body.append(dialog);const expanded=()=>dialog.querySelector("img").classList.toggle("zoomed"),image=dialog.querySelector("img");dialog.querySelector(".viewer-close").onclick=()=>dialog.close();dialog.querySelector(".viewer-original").onclick=event=>{const button=event.currentTarget;if(!image.dataset.original)return;button.disabled=true;button.textContent="원본 불러오는 중";image.onload=()=>{button.hidden=true;button.disabled=false;button.textContent="원본 보기"};image.src=image.dataset.original};image.ondblclick=expanded;image.onkeydown=event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();expanded()}};dialog.onclick=event=>{if(event.target===dialog)dialog.close()};dialog.addEventListener("close",()=>{image.classList.remove("zoomed");image.removeAttribute("data-original");dialog.querySelector(".viewer-original").hidden=true})}
 return dialog
}
document.addEventListener("click",event=>{const image=event.target.closest?.(".issue-hero,.expanded-photo img,.issue-media-grid img");if(!image)return;event.preventDefault();const dialog=imageViewer();dialog.querySelector(".viewer-original").hidden=true;dialog.querySelector("img").src=image.closest("a")?.href||image.src;dialog.showModal()});
new MutationObserver(async()=>{const facts=document.querySelector(".issue-detail .issue-facts"),match=location.pathname.match(/^\/issues\/([^/]+)$/);if(!facts||!match||facts.dataset.contractFacts)return;facts.dataset.contractFacts="loading";try{const {issue}=await api(`/issues/${match[1]}`);for(const [label,value] of [["분류",CATEGORY[issue.category]||issue.category],["회사",issue.contractorName||"미지정"],["공종",issue.tradePath||issue.tradeCode||"미지정"]]){const dt=document.createElement("dt"),dd=document.createElement("dd");dt.textContent=label;dd.textContent=value;facts.append(dt,dd)}facts.dataset.contractFacts="ready"}catch{facts.dataset.contractFacts="failed"}}).observe(document.querySelector("#app"),{childList:true,subtree:true});

